export const rewardsRouter = Router();

rewardsRouter.post('/rewards/redeem', requireUser, async (req, res) => {
  const key = req.get('Idempotency-Key');
  if (!key) return res.status(400).json({ error: 'missing key' });
  const { code } = RedeemBody.parse(req.body);
  await creditOnce({ userId: req.user.id, key, points: await pointsFor(code) });
  return res.status(204).end();
});

export const invitesRouter = Router();

invitesRouter.post('/invites/send', requireUser, async (req, res) => {
  const { address } = InviteBody.parse(req.body);
  await mailer.invite({ from: req.user.id, to: address });
  return res.status(202).end();
});
